-- SLGRVTRS D1 Analytics Warehouse -- Migration 0001 -- -- Schema designed for Selangor voter demographics: 22 Parliaments, 56 DUNs, 945 DMs -- Pre-aggregated tables to avoid expensive COUNT/GROUP BY at runtime -- -- Reference: docs/CLOUDFLARE_D1_DATABASE.md -- -- Apply: npx wrangler d1 execute slgrvtrs-voters --remote --file=./migrations/0001_analytics_warehouse.sql -- Verify: npx wrangler d1 execute slgrvtrs-voters --remote --command="SELECT name FROM sqlite_master WHERE type='table' ORDER BY name" -- ============================================================ -- 1. PARLIAMENT-LEVEL AGGREGATED STATISTICS (22 rows) -- ============================================================ CREATE TABLE IF NOT EXISTS parliaments (  code_parlimen   TEXT PRIMARY KEY,          -- 'P.092'  name            TEXT NOT NULL,              -- 'SABAK BERNAM'  voter_prefix    TEXT NOT NULL,              -- '092' (zero-padded, matches GeoJSON voter_prefix)  total_voters    INTEGER NOT NULL DEFAULT 0,  male            INTEGER NOT NULL DEFAULT 0,  female          INTEGER NOT NULL DEFAULT 0,  male_pct        REAL NOT NULL DEFAULT 0,  female_pct      REAL NOT NULL DEFAULT 0,  malay_pct       REAL NOT NULL DEFAULT 0,  chinese_pct     REAL NOT NULL DEFAULT 0,  indian_pct      REAL NOT NULL DEFAULT 0,  other_pct       REAL NOT NULL DEFAULT 0,  age_mean        REAL NOT NULL DEFAULT 0,  age_median      REAL NOT NULL DEFAULT 0,  contact_pct     REAL NOT NULL DEFAULT 0,  child_dun_count INTEGER NOT NULL DEFAULT 0,  -- GeoJSON geometry as text (D1 has no Spatialite)  geom            TEXT,  -- Metadata  created_at      TEXT NOT NULL DEFAULT (datetime('now')),  updated_at      TEXT NOT NULL DEFAULT (datetime('now')) ); -- ============================================================ -- 2. DUN-LEVEL AGGREGATED STATISTICS (56 rows) -- ============================================================ CREATE TABLE IF NOT EXISTS duns (  code_dun        TEXT PRIMARY KEY,           -- 'N.01'  name            TEXT NOT NULL,               -- 'SUNGAI AIR TAWAR'  code_parlimen   TEXT NOT NULL REFERENCES parliaments(code_parlimen),  voter_prefix    TEXT NOT NULL,               -- '01' (zero-padded, matches GeoJSON voter_prefix)  total_voters    INTEGER NOT NULL DEFAULT 0,  male            INTEGER NOT NULL DEFAULT 0,  female          INTEGER NOT NULL DEFAULT 0,  male_pct        REAL NOT NULL DEFAULT 0,  female_pct      REAL NOT NULL DEFAULT 0,  malay_pct       REAL NOT NULL DEFAULT 0,  chinese_pct     REAL NOT NULL DEFAULT 0,  indian_pct      REAL NOT NULL DEFAULT 0,  other_pct       REAL NOT NULL DEFAULT 0,  age_mean        REAL NOT NULL DEFAULT 0,  age_median      REAL NOT NULL DEFAULT 0,  contact_pct     REAL NOT NULL DEFAULT 0,  dm_count        INTEGER NOT NULL DEFAULT 0,  locality_count  INTEGER NOT NULL DEFAULT 0,  -- GeoJSON geometry as text  geom            TEXT,  -- Metadata  created_at      TEXT NOT NULL DEFAULT (datetime('now')),  updated_at      TEXT NOT NULL DEFAULT (datetime('now')) ); -- ============================================================ -- 3. DM-LEVEL AGGREGATED STATISTICS (945 rows) -- ============================================================ CREATE TABLE IF NOT EXISTS dms (  dm_code         TEXT PRIMARY KEY,           -- 'DM01'  name            TEXT NOT NULL,  dun_code        TEXT NOT NULL REFERENCES duns(code_dun),  code_parlimen   TEXT NOT NULL,  voter_prefix    TEXT NOT NULL,  total_voters    INTEGER NOT NULL DEFAULT 0,  male            INTEGER NOT NULL DEFAULT 0,  female          INTEGER NOT NULL DEFAULT 0,  male_pct        REAL,  female_pct      REAL,  malay_pct       REAL,  chinese_pct     REAL,  indian_pct      REAL,  other_pct       REAL,  age_mean        REAL,  age_median      REAL,  contact_pct     REAL,  centroid_lng    REAL,  centroid_lat    REAL,  -- Metadata  created_at      TEXT NOT NULL DEFAULT (datetime('now')),  updated_at      TEXT NOT NULL DEFAULT (datetime('now')) ); -- ============================================================ -- 4. INDEXES -- Optimized for the 4 hot query patterns (see CLOUDFLARE_D1_DATABASE.md §7) -- ============================================================ -- DUN lookups under a Parliament (drill-down pattern) CREATE INDEX IF NOT EXISTS idx_duns_parlimen ON duns(code_parlimen); -- DM lookups under a DUN (drill-down pattern) CREATE INDEX IF NOT EXISTS idx_dms_dun ON dms(dun_code); -- DM lookups under a Parliament (skip DUN level) CREATE INDEX IF NOT EXISTS idx_dms_parlimen ON dms(code_parlimen); -- DM centroid spatial hint (range queries by lat/lng) CREATE INDEX IF NOT EXISTS idx_dms_centroid ON dms(centroid_lng, centroid_lat); -- ============================================================ -- 5. DATA VERSION MANIFEST (single row) -- ============================================================ CREATE TABLE IF NOT EXISTS data_version (  id              INTEGER PRIMARY KEY CHECK (id = 1),  version         TEXT NOT NULL DEFAULT '0.0.0',  source_files    TEXT NOT NULL DEFAULT '[]',       -- JSON array of source file hashes  loaded_at      TEXT NOT NULL DEFAULT (datetime('now')),  row_counts     TEXT NOT NULL DEFAULT '{}'        -- JSON: {"parliaments": 22, "duns": 56, "dms": 945} ); -- Seed the manifest row INSERT OR IGNORE INTO data_version (id) VALUES (1); -- ============================================================ -- 6. VOTER TABLE (Phase 5 — individual records) -- -- WARNING: 3.97M rows. Load via wrangler d1 import, NOT per-row INSERT. -- Commented out until Phase 5. Uncomment and apply as migration 0002. -- ============================================================ -- CREATE TABLE IF NOT EXISTS voters ( --   id              INTEGER PRIMARY KEY AUTOINCREMENT, --   voter_id        TEXT NOT NULL UNIQUE, --   dm_code         TEXT NOT NULL, --   dun_code        TEXT NOT NULL, --   parlimen_code   TEXT NOT NULL, --   age             INTEGER NOT NULL, --   gender          TEXT NOT NULL CHECK(gender IN ('M', 'F')), --   race            TEXT NOT NULL, --   locality        TEXT NOT NULL DEFAULT '', --   has_contact     INTEGER NOT NULL DEFAULT 0 -- ); -- -- CREATE INDEX IF NOT EXISTS idx_voters_dm ON voters(dm_code); -- CREATE INDEX IF NOT EXISTS idx_voters_dun ON voters(dun_code); -- CREATE INDEX IF NOT EXISTS idx_voters_parl ON voters(parlimen_code); -- CREATE INDEX IF NOT EXISTS idx_voters_age ON voters(age); -- CREATE INDEX IF NOT EXISTS idx_voters_race ON voters(race);